@use 'tokens' as *;

@mixin scrollbar(
  $size: 10px,
  $track-color: $neutral-100,
  $thumb-color: $neutral-300,
  $thumb-hover-color: $neutral-400
) {
  scrollbar-color: $thumb-color $track-color;
  scrollbar-width: thin;

  &::-webkit-scrollbar {
    width: $size;
    height: $size;
  }

  &::-webkit-scrollbar-track {
    border-radius: $radius-pill;
    background: $track-color;
  }

  &::-webkit-scrollbar-thumb {
    border: 2px solid $track-color;
    border-radius: $radius-pill;
    background: $thumb-color;
  }

  &::-webkit-scrollbar-thumb:hover {
    background: $thumb-hover-color;
  }
}

// 스크롤(overflow) 영역 안에서 포커스 테두리가 잘리지 않도록 테두리 폭만큼 여유를 줍니다.
// padding과 같은 값의 음수 margin을 함께 써서 콘텐츠 위치는 그대로 유지됩니다.
@mixin focus-ring-room {
  margin: -$focus-ring-space;
  padding: $focus-ring-space;
  scroll-padding: $focus-ring-space; // 포커스 이동으로 스크롤될 때도 테두리까지 보이게
}
