@use 'sass:list';
@use 'tokens' as *;

// 교육원 메인 (Figma 최종 확정안 A안 로그인 전·후 PC)
// 퀵메뉴 카드(.main-b-quick__card)와 섹션 타이틀(.main-section-heading)은 대표 메인 스타일을 재사용합니다.
$edu-main-ink: $neutral-900;
$edu-main-copy: $neutral-800;
$edu-main-purple: $primary-600;

.edu-main-page .layout-container:not(.site-footer__inner) {
  width: min(1440px, calc(100% - 40px));
}

.edu-main {
  color: $edu-main-ink;

  .main-section-heading__more .material-symbols-rounded {
    font-size: 16px;
  }
}

// 메인 배너 + 우측 카드
.edu-main-hero {
  padding: 80px 0 60px;
  background: $white;

  &__inner {
    display: grid;
    grid-template-columns: minmax(0, 1fr) 376px;
    gap: 40px;
    min-height: 596px;
  }

  &__visual {
    display: flex;
    flex-direction: column;
    gap: 40px;
    min-width: 0;

    h1 {
      margin: 0;
      padding: 0 12px;
      color: $edu-main-copy;
      // 1920 기준 60px, 좁은 PC·태블릿에서는 줄바꿈되지 않도록 화면 폭에 맞춰 줄임
      font-size: clamp(40px, 3.2vw, 60px);
      line-height: 1.25;
      letter-spacing: -0.01em;
      word-break: keep-all;

      span {
        display: block;
      }
    }

    img {
      flex: 1 1 0;
      width: 100%;
      min-height: 0;
      border-radius: $radius-md;
      object-fit: cover;
      opacity: 0.9;
    }
  }

  &__cards {
    display: flex;
    flex-direction: column;
    gap: 20px;

    &[hidden] {
      display: none;
    }
  }
}

.edu-main-banner {
  position: relative;
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 12px;
  padding: 32px 24px;
  overflow: hidden;
  border: 1px solid $neutral-300;
  border-radius: $radius-md;
  background: $white;
  transition: border-color 0.2s ease;

  strong {
    position: relative;
    z-index: 1;
    color: $edu-main-copy;
    font-size: 20px;
    line-height: 1.5;
  }

  > span {
    position: relative;
    z-index: 1;
    color: $text-auth-secondary;
    font-size: 16px;
    line-height: 1.5;
  }

  em {
    position: relative;
    z-index: 1;
    display: inline-flex;
    align-items: center;
    gap: 4px;
    margin-top: 8px;
    color: $edu-main-copy;
    font-size: 14px;
    font-style: normal;
    font-weight: 700;
    line-height: 1.5;

    .material-symbols-rounded {
      font-size: 16px;
    }
  }

  img {
    position: absolute;
    right: 8px;
    bottom: -4px;
    width: 152px;
    height: 152px;
    object-fit: contain;
    mask-image: linear-gradient(to right, rgb(0 0 0 / 14%) 10%, #000 90%);
  }

  @media (hover: hover) {
    &:hover {
      border-color: $edu-main-purple;
    }
  }

  // 회원증카드 일러스트는 Figma에 그라데이션 마스크가 없음
  &--member img {
    mask-image: none;
  }
}

// 로그인 후 학습 진도 현황
.edu-main-progress {
  display: flex;
  flex-direction: column;
  gap: 24px;
  padding: 24px 24px 20px;
  border: 1px solid $edu-main-purple;
  border-radius: $radius-md;
  background: $white;

  &[hidden] {
    display: none;
  }

  &__header {
    position: relative;

    p {
      margin: 0 0 4px;
      color: $edu-main-purple;
      font-size: 16px;
      font-weight: 700;
      line-height: 1.5;
    }

    h2 {
      margin: 0;
      color: $edu-main-copy;
      font-size: 24px;
      line-height: 1.4;
      letter-spacing: -0.072px;
    }

    a {
      position: absolute;
      right: 0;
      bottom: 4px;
      display: inline-flex;
      align-items: center;
      gap: 4px;
      color: $neutral-500;
      font-size: 16px;
      font-weight: 700;
      line-height: 1.5;

      .material-symbols-rounded {
        font-size: 16px;
      }
    }
  }

  &__stats {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin: 0;

    div {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 16px;
      min-height: 60px;
      padding: 14px 16px;
      border-radius: 12px;
      background: $surface-auth;
    }

    dt {
      color: $neutral-500;
      font-size: 16px;
      font-weight: 700;
      line-height: 1.5;
    }

    dd {
      margin: 0;
      color: $edu-main-copy;
      font-size: 18px;
      font-weight: 700;
      line-height: 1.5;

      span {
        color: $neutral-500;
      }
    }
  }

  // 피그마: 통계 카드와 수강 중인 강좌 카드 간격 8px
  &__course {
    display: flex;
    flex-direction: column;
    margin-top: -16px;
    padding: 20px 16px;
    border-radius: 12px;
    background: $surface-auth;

    p {
      margin: 0 0 12px;
      color: $neutral-500;
      font-size: 16px;
      font-weight: 700;
      line-height: 1.5;
    }

    strong {
      overflow: hidden;
      color: $edu-main-copy;
      font-size: 18px;
      line-height: 1.5;
      text-overflow: ellipsis;
      white-space: nowrap;
    }

    .ds-button {
      width: 100%;
      height: 44px;
      min-height: 44px;
      margin-top: 16px;
    }
  }

  &__date {
    display: flex;
    align-items: center;
    height: 30px;
    color: $neutral-500;
    font-size: 14px;
    line-height: 1.5;
  }

  &__bar {
    display: flex;
    align-items: center;
    gap: 16px;
    height: 34px;

    progress {
      flex: 1;
      height: 12px;
      overflow: hidden;
      border: 0;
      border-radius: $radius-pill;
      background: $neutral-200;
      appearance: none;

      &::-webkit-progress-bar {
        background: $neutral-200;
      }

      &::-webkit-progress-value {
        border-radius: $radius-pill;
        background: $edu-main-purple;
      }

      &::-moz-progress-bar {
        border-radius: $radius-pill;
        background: $edu-main-purple;
      }
    }

    b {
      color: $edu-main-copy;
      font-size: 18px;
      line-height: 1.5;
    }
  }
}

// 퀵메뉴 6개 한 줄
.edu-main-quick {
  background: $white;

  &__grid {
    display: grid;
    grid-template-columns: repeat(6, minmax(0, 1fr));
    gap: 16px;

    .main-b-quick__card {
      height: 155.5px;
    }
  }
}

// 섹션 공통
.edu-main-section {
  // 카드가 오른쪽으로 이어지는 슬라이더이므로 섹션 밖으로 넘치는 부분만 숨깁니다.
  overflow: hidden;
  padding: 80px 0;
  background: $white;

  &__inner {
    display: flex;
    flex-direction: column;
    gap: 32px;
  }

  &--offline {
    background: #fcfcfc;
  }

  &--cyber {
    padding-bottom: 120px;
    background: #f1f8ff;
  }

  .edu-main-slider {
    width: 100%;
    overflow: visible;

    .swiper-wrapper {
      margin: 0;
      padding: 0;
      list-style: none;
    }
  }
}

.edu-main-empty {
  margin: 0;
  padding: 80px 0;
  color: $neutral-500;
  font-size: 16px;
  text-align: center;
}

// 공지사항
.edu-main-notice {
  &__list {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 16px 24px;
    margin: 0;
    padding: 0;
    list-style: none;
  }

  &__item a {
    display: flex;
    flex-direction: column;
    gap: 8px;
    height: 100%;
    padding: 24px;
    border: 1px solid $neutral-200;
    border-radius: 24px;
    background: $white;
    transition: border-color 0.2s ease;

    &:focus-visible {
      border-color: $primary-300;
    }

    @media (hover: hover) {
      &:hover {
        border-color: $primary-300;
      }
    }

    time {
      margin-top: 4px;
      color: $neutral-400;
      font-size: 16px;
      line-height: 1.5;
    }
  }

  // 제목은 한 줄 말줄임, 새 창 아이콘은 제목 길이와 관계없이 항상 표시
  &__title {
    display: flex;
    align-items: center;
    gap: 4px;
    min-width: 0;
    color: $edu-main-copy;
    font-size: 20px;
    line-height: 1.5;
  }

  &__title-text {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  &__external {
    flex: none;
    font-size: 0.9em;
    font-weight: 400;
  }

  &__description {
    display: -webkit-box;
    overflow: hidden;
    color: $text-auth-secondary;
    font-size: 16px;
    line-height: 1.5;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 2;
  }
}

// 현장 교육 카드: 분류별 색상
.edu-main-course {
  $tones: (
    central: (
      #f7f7ff,
      #ebe9ff,
      #44217d,
      $edu-main-purple,
    ),
    region: (
      #f0f7ff,
      #e0eeff,
      #1117bb,
      #545afb,
    ),
    group: (
      #ecfff7,
      #d2f9ea,
      #028852,
      #03ab67,
    ),
    society: (
      #fff7e0,
      #ffedb8,
      #faa02e,
      #e98c11,
    ),
  );

  width: 380px;
  height: 400px;

  a {
    position: relative;
    display: flex;
    flex-direction: column;
    height: 100%;
    padding: 40px 24px;
    overflow: hidden;
    border-radius: 24px;
    transition: box-shadow 0.2s ease;

    @media (hover: hover) {
      &:hover {
        box-shadow: $shadow-md;
      }
    }

    &:focus-visible {
      box-shadow: $shadow-md;
    }
  }

  &__chip {
    align-self: flex-start;
    padding: 6px 10px;
    border-radius: 99px;
    font-size: 12px;
    font-weight: 600;
    line-height: 1.5;
  }

  &__title {
    display: -webkit-box;
    min-height: 67px;
    margin-top: 12px;
    overflow: hidden;
    font-size: 24px;
    line-height: 1.4;
    letter-spacing: -0.072px;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 2;
  }

  &__info {
    display: flex;
    flex-direction: column;
    gap: 4px;
    // Figma: 칩·제목과 수강일 박스를 합친 영역 높이 200px
    margin: 21px 0 0;
    padding: 12px;
    border-radius: 8px;
    color: #39414b;
    font-size: 14px;
    line-height: 1.5;

    div {
      display: flex;
      gap: 8px;
    }

    dd {
      margin: 0;
      font-weight: 700;
    }
  }

  // "평점"을 "수강일" 폭에 맞춰 양끝 정렬 (현장교육 리스트 .ofe-data__label--spread와 같은 방식)
  &__label--spread {
    display: inline-flex;
    justify-content: space-between;
    width: 2.6em; // "수강일" 글자 폭과 동일
  }

  &__status {
    position: relative;
    z-index: 1;
    margin-top: auto;
    color: $edu-main-copy;
    font-size: 18px;
    font-weight: 700;
    line-height: 1.5;

    &--closed {
      color: $neutral-400;
    }
  }

  // Figma 이미지 영역(216x160, 카드 우하단) 안에서 그림별 크기·위치
  &__art {
    --art-scale: 1;
    --art-w: 160px;
    --art-h: 136px;
    --art-right: 11px;
    --art-bottom: 14px;
    position: absolute;
    right: calc(var(--art-right) * var(--art-scale));
    bottom: calc(var(--art-bottom) * var(--art-scale));
    width: calc(var(--art-w) * var(--art-scale));
    height: calc(var(--art-h) * var(--art-scale));
    pointer-events: none;

    &[src*='art-pin'] {
      --art-w: 171px;
      --art-h: 110px;
      --art-right: 21px;
      --art-bottom: 26px;
    }
    &[src*='art-wave'] {
      --art-w: 151px;
      --art-h: 126px;
      --art-right: 19px;
      --art-bottom: 19px;
    }
    &[src*='art-ring'] {
      --art-w: 173px;
      --art-h: 171px;
      --art-right: 11px;
      --art-bottom: -8px;
    }
  }

  @each $name, $tone in $tones {
    &--#{$name} {
      a {
        background: list.nth($tone, 1);
      }

      .edu-main-course__chip,
      .edu-main-course__info {
        background: list.nth($tone, 2);
      }

      .edu-main-course__chip {
        color: list.nth($tone, 3);
      }

      .edu-main-course__title {
        color: list.nth($tone, 4);
      }
    }
  }

  &--central &__status--open {
    color: $edu-main-purple;
  }
}

// 사이버 교육 카드
.edu-main-cyber {
  width: 380px;
  height: 432px;

  a {
    display: flex;
    flex-direction: column;
    height: 100%;
    overflow: hidden;
    border: 1px solid $neutral-200;
    border-radius: 24px;
    background: $white;
    transition: box-shadow 0.2s ease;

    @media (hover: hover) {
      &:hover {
        box-shadow: $shadow-md;
      }
    }

    &:focus-visible {
      box-shadow: $shadow-md;
    }
  }

  &__thumb {
    position: relative;
    flex: none;
    height: 190px;
    background: linear-gradient(180deg, #dad5f8 1%, #cfcaf5 94%);

    img {
      width: 100%;
      height: 100%;
      object-fit: cover;
      opacity: 0.8;
    }
  }

  &__chip {
    position: absolute;
    top: 24px;
    left: 24px;
    padding: 6px 10px;
    border-radius: 99px;
    font-size: 12px;
    font-weight: 600;
    line-height: 1.5;

    &--purple {
      color: #44217d;
      background: #ebe9ff;
    }

    &--blue {
      color: #1117bb;
      background: #e0eeff;
    }

    &--yellow {
      color: #faa02e;
      background: #ffedb8;
    }
  }

  &__body {
    display: flex;
    flex: 1;
    flex-direction: column;
    gap: 8px;
    padding: 22px 22px 32px;
  }

  &__title {
    display: -webkit-box;
    overflow: hidden;
    color: $edu-main-copy;
    font-size: 24px;
    line-height: 1.4;
    letter-spacing: -0.072px;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 2;
  }

  &__description {
    display: -webkit-box;
    overflow: hidden;
    color: #39414b;
    font-size: 16px;
    line-height: 1.5;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 2;
  }

  &__point {
    margin-top: auto;
    padding: 12px;
    border-radius: 8px;
    color: #39414b;
    background: $surface-auth;
    font-size: 14px;
    line-height: 1.5;

    b {
      margin-left: 8px;
    }
  }
}

@media (max-width: 1100px) {
  .edu-main-hero__inner {
    grid-template-columns: minmax(0, 1fr);
    min-height: 0;
  }

  .edu-main-hero__visual h1 {
    font-size: 40px;
  }

  // 한 열 배치에서는 부모 높이가 없어 flex: 1 1 0이면 높이가 0이 되므로 고정 높이로 둠
  .edu-main-hero__visual img {
    flex: none;
    height: 360px;
  }

  .edu-main-hero__cards {
    flex-direction: row;

    .edu-main-banner {
      min-height: 240px;
    }
  }

  .edu-main-quick__grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .edu-main-notice__list {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

// 모바일(767px 이하): Figma 수정안 교육원 메인_MO (360px 기준)
@media (max-width: $breakpoint-mobile) {
  .edu-main-page .edu-main-hero__inner,
  .edu-main-page .edu-main-quick .layout-container {
    width: calc(100% - 24px);
  }

  .edu-main-page .edu-main-section__inner {
    width: calc(100% - 40px);
  }

  .edu-main .main-section-heading__more .material-symbols-rounded {
    font-size: 24px;
  }

  // 분류 탭: Figma 좌우 여백 8px
  .edu-main-section .ds-tabs {
    padding-inline: 8px;
  }

  // 메인 비주얼: 제목 28px, 이미지 높이 192, 카드 2개 세로 배치
  .edu-main-hero {
    padding: 40px 0;

    &__inner {
      gap: 20px;
    }

    &__visual {
      gap: 24px;

      h1 {
        padding: 0;
        color: $neutral-800;
        font-size: 28px;
        line-height: 1.3;
        letter-spacing: -0.28px;
        word-break: keep-all;
      }

      img {
        flex: none;
        height: 192px;
        border-radius: $radius-lg;
      }
    }

    &__cards {
      flex-direction: column;
      gap: 12px;

      .edu-main-banner {
        min-height: 263px;
      }
    }
  }

  .edu-main-banner {
    flex: none;
    padding: 32px 24px;

    strong {
      line-height: 1.4;
      letter-spacing: -0.06px;
    }

    img {
      right: 1px;
      bottom: -9px;
    }
  }

  // 학습 진도 현황: 제목 한 줄, 통계 카드 높이 균등(정보 영역 432)
  .edu-main-progress {
    gap: 20px;
    padding: 24px 20px;

    &__break {
      display: none;
    }

    &__header {
      h2 {
        margin-top: 4px;
        font-size: 20px;
        letter-spacing: -0.06px;
      }

      a {
        position: static;
        margin-top: 12px;
      }
    }

    &__stats div {
      min-height: 68px;
      padding: 12px;
    }

    &__course {
      margin-top: -12px;
      padding: 12px;

      p {
        margin-bottom: 8px;
      }

      strong {
        font-size: 16px;
      }
    }
  }

  // 주요 서비스: 2열 카드(162x136)
  .edu-main-quick__grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 12px;

    .main-b-quick__card {
      width: auto;
      height: 136px;
      padding: 20px 16px;
      border-radius: $radius-md;

      strong {
        font-size: 18px;
      }
    }
  }

  .edu-main-section {
    padding: 40px 0;

    &__inner {
      gap: 24px;
    }

    &--cyber {
      padding-bottom: 60px;
    }
  }

  // 공지사항: 2행 가로 스크롤 카드(274px)
  .edu-main-notice__list {
    grid-template-rows: repeat(2, auto);
    grid-template-columns: none;
    grid-auto-columns: 274px;
    grid-auto-flow: column;
    gap: 16px;
    width: calc(100% + 20px);
    overflow-x: auto;
    padding-right: 20px;
    scroll-snap-type: x mandatory;
    scrollbar-width: none;

    &::-webkit-scrollbar {
      display: none;
    }
  }

  .edu-main-notice__item {
    scroll-snap-align: start;
  }

  .edu-main-notice__title {
    font-size: 18px;
  }

  // 현장 교육 카드 290x330
  .edu-main-course {
    width: 290px;
    height: 330px;

    a {
      padding: 24px 20px;
      border-radius: $radius-md;
    }

    &__title {
      min-height: 0;
      font-size: 20px;
      letter-spacing: -0.06px;
    }

    &__info {
      margin-top: 20px;
    }

    &__status {
      font-size: 16px;
    }

    // 모바일 이미지 영역 160x118 (PC 216x160 비율 축소)
    &__art {
      --art-scale: 0.7407;
    }
  }

  // 사이버 교육 카드 292x348
  .edu-main-cyber {
    width: 292px;
    height: 348px;

    a {
      border-radius: $radius-md;
    }

    &__thumb {
      height: 145px;
    }

    &__chip {
      top: 19px;
      left: 19px;
    }

    &__body {
      gap: 6px;
      padding: 19px 19px 20px;
    }

    &__title {
      font-size: 20px;
      letter-spacing: -0.06px;
    }

    &__description {
      font-size: 14px;
    }

    &__point {
      padding: 9px;
      border-radius: 6px;
    }
  }
}

// 첫 로딩 시 제목 두 줄 → 이미지 순서로 fade up
.edu-main-hero__visual {
  h1 > span,
  > img {
    animation: edu-main-fade-up 1200ms cubic-bezier(0.22, 1, 0.36, 1) both;
  }

  h1 > span:nth-child(2) {
    animation-delay: 240ms;
  }

  > img {
    animation-delay: 520ms;
  }
}

@keyframes edu-main-fade-up {
  from {
    opacity: 0;
    transform: translateY(24px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (prefers-reduced-motion: reduce) {
  .edu-main-hero__visual h1 > span,
  .edu-main-hero__visual > img {
    animation: none;
  }
}

// 태블릿(768~1100): 교육원 메인 헤더를 대표 메인과 같게(높이 101.687 · 위 40 · 아래 20, 로고 하단 정렬)
@media (min-width: ($breakpoint-mobile + 1)) and (max-width: 1100px) {
  body.edu-main-page .site-header__inner {
    align-items: flex-end;
    height: 101.687px;
    padding-top: 40px;
    padding-bottom: 20px;
  }
}
